-- D5: real, source-cited storage & processing facilities for Tamil Nadu.
--
-- Every row below traces to a government directory that was fetched live on
-- 2026-09-10. No facility here is inferred, estimated or filled in from a
-- secondary mention — anything that could not be confirmed against a primary
-- directory is in docs/facilities/unverified-leads.md instead, NOT in this file.
--
-- Provenance columns are added first: a bare facility name with no citation is
-- not a usable record, so source/url/access-date/verification note are stored
-- per row alongside the facility itself.
--
-- READ THIS BEFORE USING THESE ROWS FOR STORE/PROCESS SCORING:
-- none of the accessible directories publish the economic parameters the
-- engine actually needs (cost_per_kg_per_day, max_storage_days, storage_temp_c,
-- gate_price_per_kg, yield_ratio). Those columns are deliberately NULL.
-- See docs/facilities/sourcing-report.md.

ALTER TABLE "storage_facility"
  ADD COLUMN IF NOT EXISTS "district" text,
  ADD COLUMN IF NOT EXISTS "source_name" text,
  ADD COLUMN IF NOT EXISTS "source_url" text,
  ADD COLUMN IF NOT EXISTS "source_accessed_on" date,
  ADD COLUMN IF NOT EXISTS "verification_note" text,
  ADD COLUMN IF NOT EXISTS "in_covered_district" boolean;
